CREATE FUNCTION public.onboarding_review_save(aid uuid,stage text,decision text,note text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b assessment_batteries;p jsonb;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO b FROM assessment_batteries WHERE id=aid FOR UPDATE;IF stage NOT IN ('analysis','battery') OR decision NOT IN ('in_review','approved','rejected') OR btrim(note)='' OR NOT org_can(CASE WHEN decision='in_review' THEN 'analysis' ELSE 'approve' END,aid) THEN RAISE EXCEPTION 'Authorized review required';END IF;p:=b.payload||jsonb_build_object(CASE WHEN stage='analysis' THEN 'analysis_status' ELSE 'status' END,decision,'history',coalesce(b.payload->'history','[]')||jsonb_build_array(jsonb_build_object('date',now(),'action',stage||': '||decision||' — '||note,'by',auth.uid())));UPDATE assessment_batteries SET payload=p,status=p->>'status',analysis_status=p->>'analysis_status' WHERE id=aid;RETURN true;END $$; REVOKE ALL ON FUNCTION onboarding_review_save(uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION onboarding_review_save(uuid,text,text,text) TO authenticated;